 const ordered=ds.toSorted((a,b)=>a.at-b.at),groups=[];let outside=0;for(const e of ordered){if(e.start)groups.push([e]);else if(groups.length)groups.at(-1).push(e);else outside+=e.count;}const longest=Math.max(0,...groups.map(g=>Math.floor((g.at(-1).at-g[0].at)/DAY))),gap=Math.max(0,...ordered.slice(1).map((e,i)=>Math.max(0,Math.floor((e.at-ordered[i].at)/DAY)-1))),between=Math.max(0,...groups.slice(1).map((g,i)=>Math.max(0,Math.floor((g[0].at-groups[i].at(-1).at)/DAY))));
