function toggle(k,title,desc){return `<label class="setting-row"><div class="info"><h3>${title}</h3><p>${desc}</p></div><input type="checkbox" class="switch" data-setting="${k}" aria-label="${title}" ${data.settings[k]?'checked':''}></label>`}
