function screeningRead(e){
 const states=normalizeScreening(e.screening),d=normalizeLabDetails(e.labDetails),labels={negative:'Negativo',positive:'Positivo'};
 const row=(label,value,cls='')=>value?`<div class="test-row ${cls}"><span>${esc(label)}</span><strong>${esc(value)}</strong></div>`:'';
 let html=SCREENING_GROUPS.map(([group,tests])=>{const rows=tests.filter(([key])=>states[key]!=='untested').map(([key,label])=>row(label,labels[states[key]],states[key])).join('');return rows?`<section class="screening-section"><h3>${esc(group)}</h3>${rows}</section>`:''}).join('');
 const details=[['TPHA',labels[d.tpha]],['RPR',labels[d.rpr]],['IgG / IgM',d.iggIgm],['IgG (precedente)',d.igg],['IgM (precedente)',d.igm],['HBsAg',labels[d.hbsag]],['Anti HBs · valore',d.antiHbs],['Anti HBs · esito',labels[d.antiHbsState]],['HBc Totale · valore',d.hbc],['HBc Totale · esito',labels[d.hbcState]]].map(([k,v])=>row(k,v)).join('')+row('Creatinina · mg/dL',d.creatinine,creatinineStatus(d.creatinine));
 if(details)html+=`<section class="screening-section"><h3>Valori e dettagli</h3>${details}</section>`;
 modal(`<h2>Esiti analisi</h2><p>${fmt(e.at)}</p>${html||'<p>Nessun esame compilato.</p>'}${d.syphilisNotes?`<h3>Note sifilide</h3><p class="read-notes">${esc(d.syphilisNotes)}</p>`:''}${e.results?`<h3>Altri risultati</h3><p class="read-notes">${esc(e.results)}</p>`:''}${e.notes?`<h3>Note</h3><p class="read-notes">${esc(e.notes)}</p>`:''}<div class="buttons"><button class="secondary" data-action="close">Chiudi</button><button class="primary" data-edit="${esc(e.id)}">Modifica</button></div>`);
}
