 modal(`<h2>${existing?'Modifica esiti analisi':'Nuovi esiti analisi'}</h2><form id="screening-form"><section class="screening-section"><h3>Dettagli esami</h3><div class="screening-fields"><label for="screening-at">Data e ora degli esami</label><input id="screening-at" type="datetime-local" required max="${localInput(Date.now())}" value="${localInput(existing?.at||Date.now())}"></div></section><section class="screening-section"><h3>Esami del sangue</h3><div class="screening-tests">${blood}<div class="creatinine-field">${numeric('creatinine','Creatinina · mg/dL')}<small id="creatinine-range">Intervallo indicato: 0,70–1,20 mg/dL</small></div></div></section><details class="more-tests"><summary>Altri esami <span>More</span></summary>${SCREENING_GROUPS.slice(1).map(([group,tests])=>`<section class="screening-section"><h3>${esc(group)}</h3><div class="screening-tests">${tests.map(([key,label])=>statusButton(key,group+' · '+label)).join('')}</div></section>`).join('')}</details><section class="screening-section"><h3>Altri risultati</h3><div class="screening-fields"><textarea id="screening-extra" rows="3" maxlength="10000" aria-label="Altri risultati">${esc(existing?.results||'')}</textarea></div></section><section class="screening-section"><h3>Note</h3><div class="screening-fields"><textarea id="screening-notes" rows="3" maxlength="10000" aria-label="Note degli esami">${esc(existing?.notes||'')}</textarea></div></section><div class="error" id="form-error" role="alert"></div><div class="buttons"><button type="button" class="secondary" data-action="close">Annulla</button><button class="primary">Salva esiti</button></div></form>`);
 const showRange=()=>{const el=document.querySelector('[data-lab="creatinine"]');el.className='lab-number '+creatinineStatus(el.value);};showRange();
