 document.querySelectorAll('[data-result],[data-lab-state]').forEach(b=>b.onclick=()=>{const key=b.dataset.result||b.dataset.labState,target=b.dataset.result?states:details;target[key]=RESULT_STATES[(RESULT_STATES.indexOf(target[key])+1)%RESULT_STATES.length];b.className='result-state '+target[key];b.textContent=labels[target[key]];b.setAttribute('aria-label',b.getAttribute('aria-label').split(':')[0]+': '+labels[target[key]]);document.querySelectorAll('[data-dependent]').forEach(el=>el.hidden=states[el.dataset.dependent]==='untested');});
 $('#screening-form').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;try{const at=new Date($('#screening-at').value).getTime();if(!Number.isFinite(at)||at<Date.UTC(2000,0,1)||at>Date.now()+60000)throw Error('Inserisci la data effettiva degli esami.');const ev={id:existing?.id||crypto.randomUUID(),type:'health',category:'screening',title:'Esiti analisi',at,screening:{...states},labDetails:normalizeLabDetails(details),results:$('#screening-extra').value,notes:$('#screening-notes').value};await save({...data,events:[...data.events.filter(x=>x.id!==ev.id),ev]});$('#modal').close();toast('Esiti salvati');}catch(err){$('#form-error').textContent=err.message}finally{busy=false}};
