function changeScheme(){const a=analyze(data);modal(`<h2>Cambia schema</h2><p>Il cambio decorre da adesso e conserva tutte le registrazioni precedenti. L’orario delle dosi resta quello del ciclo in corso.</p><p>Usa esclusivamente lo schema concordato con il centro PrEP. Un cambio non corregge dosi mancanti e non conferma la copertura.</p><form id="scheme-form"><label for="scheme-mode">Schema</label><select id="scheme-mode"><option value="demand" ${a.mode==='demand'?'selected':''}>On demand · 2-1-1</option><option value="daily" ${a.mode==='daily'?'selected':''}>Quotidiano</option></select><div class="buttons"><button type="button" class="secondary" data-action="close">Annulla</button><button class="primary">Salva schema</button></div></form>`);$('#scheme-form').onsubmit=async e=>{e.preventDefault();const mode=$('#scheme-mode').value;if(mode!==a.mode)await save({...data,events:[...data.events,{id:crypto.randomUUID(),type:'scheme',at:Date.now(),mode}]});$('#modal').close();};}
function guide(){if(analyze(data).mode==='daily'){modal(`<h2>Schema quotidiano</h2><p>Registra la dose iniziale di 2 compresse prevista dalla tua prescrizione, poi 1 compressa ogni 24 ore all’orario del ciclo.</p><p>I rapporti non modificano il piano quotidiano. Il diario segnala in giallo una dose non registrata oltre 2 ore dopo l’orario previsto: questa soglia tecnica non certifica una finestra clinica di sicurezza.</p><p>Una dose saltata richiede verifica con il centro PrEP. In presenza di un’esposizione recente chiedi tempestivamente una valutazione per PEP. Il diario non prescrive un recupero né un’interruzione.</p><p>Il verde indica una previsione condizionata alla corretta assunzione. Un cambio di schema non conferma la copertura.</p><a href="https://bhiva.org/clinical-guideline/PrEP-guidelines/" target="_blank" rel="noopener">Linee guida BASHH/BHIVA</a><div class="buttons"><button class="primary" data-action="close">Ho capito</button></div>`);return;}modal(`<h2>Il tuo schema 2-1-1</h2><div class="step-list"><b>2</b><p>Dose iniziale: 2 compresse insieme, secondo la prescrizione, da 2 a 24 ore prima del rapporto.</p></div><div class="step-list"><b>1</b><p>Una compressa ogni 24 ore, all’orario fissato dalla dose iniziale.</p></div><div class="step-list"><b>1</b><p>Si continua fino a completare due assunzioni giornaliere dopo l’ultimo rapporto. Un nuovo rapporto aggiorna il conteggio.</p></div><p>Se dopo la dose iniziale non hai avuto rapporti e non ne prevedi, non è necessario continuare il ciclo. L’assenza di una registrazione non dimostra però che non ci siano stati rapporti.</p><p>Il verde è una previsione condizionata alla corretta assunzione delle dosi successive, non una garanzia di protezione. Il diario è configurato per lo schema on demand per rapporti anali.</p><p>Un ritardo o un’interruzione non genera automaticamente un consiglio di dose doppia. In presenza di dosi mancanti, date incoerenti o rapporti prima della dose iniziale, verifica tempestivamente con il centro PrEP; può essere necessaria una valutazione per PEP.</p><p>Il limite di 2 ore usato per segnalare scostamenti nel diario non certifica una finestra clinica di sicurezza. I timer seguono intervalli di 24 ore anche nei cambi di fuso o ora legale.</p><p><a href="https://www.hse.ie/conditions/hiv/how-to-take-prep/" target="_blank" rel="noopener">Indicazioni HSE sullo schema on demand</a></p><button class="primary" data-action="close">Ho capito</button>`)}
function onboarding(){modal(`<div class="onboard"><div class="brand-icon" style="width:65px;height:65px;font-size:32px">${icon('pill')}</div><h2 style="font-size:32px;margin-top:25px">Benvenuto in<br>Diario PrEP</h2><p>Il tuo diario personale, in italiano.</p><div class="step-list"><b>◷</b><div><h3>Ricorda ogni assunzione</h3><p>Orari e promemoria, un giorno alla volta.</p></div></div><div class="step-list"><b>♥</b><div><h3>Registra i rapporti</h3><p>Il diario aggiorna le dosi da completare.</p></div></div><div class="privacy"><strong>100% diario locale</strong><span>Solo gli orari degli avvisi vengono inviati al servizio notifiche.</span></div><div class="buttons"><button class="primary" data-action="setup">Cominciamo</button></div></div>`)}
async function configNotifications(){const configured=await getPush();modal(`<h2>Notifiche</h2><p>Su iPhone apri l’app dalla schermata Home e autorizza le notifiche.</p><p>${esc(syncStatus)}</p><form id="push-form"><div id="form-error" class="error"></div><div class="buttons"><button type="button" class="secondary" data-action="close">Chiudi</button><button class="primary">${configured?'Verifica notifiche':'Attiva notifiche'}</button></div></form>${configured?'<button class="ghost danger" data-action="disable-push">Disattiva su questo dispositivo</button>':''}`);$('#push-form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{await enablePush();$('#modal').close();toast('Notifiche attivate');render()}catch(err){$('#form-error').textContent=err.message}finally{b.disabled=false}}}
async function getPush(){return new Promise((resolve,reject)=>{const tx=db.transaction('state','readonly'),r=tx.objectStore('state').get('push');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
