async function api(body,token){const r=await fetch(backend,{method:'POST',headers:{'Content-Type':'application/json',apikey:publicAnonKey,Authorization:'Bearer '+publicAnonKey,...(token?{'x-device-token':token}:{})},body:JSON.stringify(body),signal:AbortSignal.timeout(15000)});if(!r.ok){const err=Error(r.status===400?'Piano promemoria rifiutato dal servizio':r.status===401?'Attivazione notifiche da rinnovare':r.status===403?'Connessione al servizio non autorizzata':'Servizio notifiche temporaneamente non disponibile');err.status=r.status;throw err;}return r.json()}
async function enablePush(){if(!('serviceWorker'in navigator)||!('PushManager'in window))throw Error('Aggiungi prima l’app alla schermata Home di iPhone, poi riaprila dall’icona.');if(await Notification.requestPermission()!=='granted')throw Error('Autorizza le notifiche nelle impostazioni del dispositivo.');const old=await getPush();if(old){await sync();if(syncStatus==='Promemoria aggiornati')return;}const {publicKey}=await api({action:'public-key'});const bytes=Uint8Array.from(atob(publicKey.replace(/-/g,'+').replace(/_/g,'/')+'='.repeat((4-publicKey.length%4)%4)),c=>c.charCodeAt(0));const reg=await navigator.serviceWorker.ready;const sub=await reg.pushManager.getSubscription()||await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:bytes});const {token}=await api({action:'register',subscription:sub.toJSON()});await putPush({token});await sync();if(syncStatus!=='Promemoria aggiornati')toast('Attivazione in corso: attendi la notifica di conferma.');}
function updateSyncBanner(){const el=$('#sync-banner');if(el){el.hidden=syncStatus==='Promemoria aggiornati';el.textContent=syncStatus.startsWith('Non attive')?(view==='home'?'Notifiche non attive · Impostazioni':'Notifiche non attive. Configurale nelle Impostazioni per ricevere i promemoria.'):syncStatus;}}
let syncTail=Promise.resolve();function sync(){syncTail=syncTail.catch(()=>{}).then(async()=>{const p=await getPush();if(!p){syncStatus='Non attive · da configurare';updateSyncBanner();const label=$('#sync-label');if(label)label.textContent=syncStatus;return;}try{const plan=[...reminderPlan(analyze(data),data.settings),...stockReminderPlan(data)];for(let attempt=0;;attempt++){try{await api({action:'sync',plan,discreet:data.settings.discreet},p.token);break}catch(err){if(err.status!==401||attempt>=2)throw err;await new Promise(resolve=>setTimeout(resolve,1500));}}syncStatus=Notification.permission==='granted'?'Promemoria aggiornati':'Autorizzazione notifiche da verificare nelle impostazioni';}catch(err){syncStatus=err.status===401?'Attivazione da rinnovare · premi Attiva notifiche':err.status===400?'Piano promemoria da aggiornare · riprova tra poco':err.status?'Servizio notifiche non disponibile · riprova tra poco':'Promemoria da sincronizzare · controlla la connessione';}updateSyncBanner();const label=$('#sync-label');if(label)label.textContent=syncStatus;});return syncTail;}
async function cancelPush(){const p=await getPush();if(p)await api({action:'remove'},p.token);const reg=await navigator.serviceWorker.ready;const sub=await reg.pushManager.getSubscription();if(sub)await sub.unsubscribe();await putPush(null);syncStatus='Non attive';}
async function exportData(){const file={format:'diario-prep',version:2,exportedAt:new Date().toISOString(),events:data.events,settings:data.settings};const blob=new Blob([JSON.stringify(file,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='diario-prep-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('Backup esportato: contiene dati personali, conservalo con cura.');}
function importData(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const f=input.files[0];if(!f)return;if(f.size>20e6)throw Error('File troppo grande.');const next=validateBackup(JSON.parse(await f.text()));modal(`<h2>Ripristina backup</h2><p>Il file contiene ${next.events.length} registrazioni. Sostituirà le ${data.events.length} attuali. Esporta prima una copia se vuoi conservarle.</p><div class="buttons"><button class="secondary" data-action="close">Annulla</button><button class="primary" id="confirm-import">Sostituisci diario</button></div>`);$('#confirm-import').onclick=async()=>{try{await save({...data,...next,onboarded:true},false);$('#modal').close();toast('Backup importato. Controlla lo stato dei promemoria.')}catch{toast('Importazione non riuscita: i dati precedenti restano disponibili.')}}}catch(e){toast(e.message)}};input.click()}
