document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{
 if(b.dataset.historyView){await save({...data,settings:{...data.settings,historyView:b.dataset.historyView}});return;}
 if(b.dataset.month){calendarMonth=new Date(calendarMonth.getFullYear(),calendarMonth.getMonth()+(+b.dataset.month),1);render();return;}
 if(b.dataset.day){const es=historyTimeline(data).filter(x=>dateKey(x.at)===b.dataset.day);modal(`<h2>${day(new Date(b.dataset.day+'T12:00:00').getTime())}</h2>${es.sort((a,b)=>b.at-a.at).map(timelineRow).join('')||'<p>Nessun evento</p>'}`);return;}
 if(b.dataset.view){view=b.dataset.view;location.hash=view;render();window.scrollTo(0,0);return}
 if(b.dataset.filter){filter=b.dataset.filter;render();return}if(b.dataset.period){period=+b.dataset.period;render();return}
 if(b.dataset.read){const ev=data.events.find(e=>e.id===b.dataset.read);if(ev?.type==='health'&&ev.category==='screening')screeningRead(ev);return;}
 if(b.dataset.edit){const ev=data.events.find(e=>e.id===b.dataset.edit);if(ev.type==='box'){boxEntry(ev);return;}if(ev.type==='health'){if(ev.category==='screening')screeningEntry(ev);else healthEntry(ev.category,ev);}else entry(ev.type,ev.start,ev);return}
 if(b.dataset.delete){const id=b.dataset.delete;modal(`<h2>Elimina registrazione</h2><p>Il conteggio e i promemoria verranno aggiornati. Puoi annullare subito dopo l’eliminazione.</p><div class="buttons"><button class="secondary" data-action="close">Annulla</button><button class="primary" id="confirm-delete">Elimina</button></div>`);$('#confirm-delete').onclick=async()=>{const old=data.events.find(e=>e.id===id);await save({...data,events:data.events.filter(e=>e.id!==id)});$('#modal').close();modal(`<h2>Registrazione eliminata</h2><div class="buttons"><button class="secondary" data-action="close">Chiudi</button><button class="primary" id="undo">Annulla eliminazione</button></div>`);$('#undo').onclick=async()=>{await save({...data,events:[...data.events,old]});$('#modal').close()}};return}
 switch(b.dataset.action){case 'status-details':modal(`<h2>Stato</h2><p>${esc(b.dataset.summary)}</p><button class="primary" data-action="close">Chiudi</button>`);break;case 'box':boxEntry();break;case 'issues':modal(`<h2>Schema da verificare</h2>${analyze(data).issues.map(x=>`<p>${esc(x)}</p>`).join('')}<p>Se riguarda un rapporto recente, contatta tempestivamente il centro PrEP per valutare cosa fare.</p><button class="primary" data-action="close">Chiudi</button>`);break;case 'screening':screeningEntry();break;case 'analysis':healthEntry('analysis');break;case 'visit':healthEntry('visit');break;case 'scheme':changeScheme();break;case 'settings':view='settings';render();break;case 'start':entry('dose',true);break;case 'dose':case 'manual':entry('dose');break;case 'sex':entry('sex');break;case 'close':$('#modal').close();break;case 'guide':guide();break;case 'export':await exportData();break;case 'import':importData();break;case 'notifications':await configNotifications();break;case 'disable-push':await cancelPush();$('#modal').close();render();toast('Notifiche disattivate');break;
 case 'setup':modal(`<h2>Il tuo schema PrEP</h2><p>Scegli lo schema concordato con il centro PrEP.</p><div class="buttons" style="flex-direction:column"><button class="primary" data-action="setup-daily">Quotidiano</button><button class="secondary" data-action="setup-demand">On demand · 2-1-1</button></div>`);break;
 case 'setup-daily':case 'setup-demand':await save({...data,events:[...data.events.filter(e=>e.type!=='scheme'),{id:crypto.randomUUID(),type:'scheme',at:Date.now(),mode:b.dataset.action==='setup-daily'?'daily':'demand'}]});modal(`<h2>Stai già assumendo PrEP?</h2><p>Registra la dose con il suo orario reale.</p><div class="buttons" style="flex-direction:column"><button class="primary" data-action="setup-dose">Sì, ho iniziato ora</button><button class="secondary" data-action="setup-done">No, inizierò quando serve</button></div>`);break;
 case 'setup-dose':modal(`<h2>La scatola è appena aperta?</h2><form id="setup-box"><label for="setup-box-kind">Scatola</label><select id="setup-box-kind"><option value="fresh">Sì, nuova da 30 compresse</option><option value="open">No, era già aperta</option></select><div id="setup-box-details" hidden><label for="setup-box-at">Data e ora di apertura</label><input id="setup-box-at" type="datetime-local" max="${localInput(Date.now())}" value="${localInput(Date.now())}"><label for="setup-box-count">Compresse disponibili prima della dose che registrerai</label><input id="setup-box-count" type="number" min="1" max="30" step="1" value="30"></div><p>La dose che registrerai sarà sottratta dalla scorta.</p><div id="form-error" class="error"></div><button class="primary">Continua alla dose</button></form>`);$('#setup-box-kind').onchange=()=>{$('#setup-box-details').hidden=$('#setup-box-kind').value==='fresh'};$('#setup-box').onsubmit=e=>{e.preventDefault();const fresh=$('#setup-box-kind').value==='fresh',at=new Date($('#setup-box-at').value).getTime(),initialCount=fresh?30:Number($('#setup-box-count').value);if(!Number.isInteger(initialCount)||initialCount<1||initialCount>30||!Number.isFinite(at)||at<Date.UTC(2000,0,1)||at>Date.now()+60000){$('#form-error').textContent='Controlla data e numero di compresse.';return}entry('dose',true,null,{fresh,at,initialCount})};break;
 case 'setup-done':await save({...data,onboarded:true});$('#modal').close();break;
 case 'reset':modal(`<h2>Reset del diario</h2><p>Cancellerà tutte le registrazioni e le impostazioni. Prima esporta un backup se vuoi conservarle. Gli avvisi sul server saranno annullati prima della cancellazione.</p><form id="reset-form"><label for="reset-word">Scrivi RESET per confermare</label><input id="reset-word" autocomplete="off" required pattern="RESET"><div id="form-error" class="error"></div><div class="buttons"><button type="button" class="secondary" data-action="close">Annulla</button><button class="primary">Cancella tutti i dati</button></div></form>`);$('#reset-form').onsubmit=async e=>{e.preventDefault();try{const p=await getPush();if(p)await api({action:'sync',plan:[],discreet:true},p.token);if(p)await cancelPush();else await putPush(null);view='home';location.hash='home';await save({events:[],settings:{...defaults},onboarded:false});$('#modal').close();onboarding()}catch{$('#form-error').textContent='Impossibile annullare gli avvisi. Riprova con una connessione attiva; il diario non è stato cancellato.'}};break;
 }}catch(err){toast(err.message||'Operazione non riuscita.')}});
document.addEventListener('change',async e=>{if(e.target.id==='theme-setting'){await save({...data,settings:{...data.settings,theme:e.target.value}});return;}if(e.target.dataset.setting){try{await save({...data,settings:{...data.settings,[e.target.dataset.setting]:e.target.checked}})}catch{toast('Impossibile salvare la preferenza.')}}});
window.addEventListener('hashchange',()=>{view=tabs.some(t=>t[0]===location.hash.slice(1))?location.hash.slice(1):'home';render()});navigator.serviceWorker?.addEventListener('message',e=>{if(e.data?.type==='push-activation')void sync()});window.addEventListener('online',()=>void sync());document.addEventListener('visibilitychange',()=>{if(!document.hidden){render();void sync()}});
try{db=await new Promise((resolve,reject)=>{const r=indexedDB.open('diario-prep-v1',1);r.onupgradeneeded=()=>r.result.createObjectStore('state');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});data=await request()||{events:[],settings:{...defaults},onboarded:false};data={...data,settings:{...defaults,...data.settings}};const observed=captureIssues(data);if(observed!==data){data=observed;await request(data);}render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>toast('Modalità offline non disponibile.'));if(!data.onboarded)onboarding();void sync();setInterval(()=>{const a=analyze(data);if(JSON.stringify([a.kind,a.next,a.continuationAt,a.canContinue,a.due])!==lastRenderedKind){const observed=captureIssues(data);if(observed!==data){data=observed;void request(data);}render();void sync();}document.documentElement.dataset.theme=themeAt(data.settings.theme);document.querySelectorAll('[data-until]').forEach(el=>{const t=+el.dataset.until;el.textContent=t<=Date.now()?'È il momento':cd(t)})},1000)}catch{$('#content').innerHTML='<h1>Archivio non disponibile</h1><p>Il browser non permette di aprire il diario locale. Controlla lo spazio disponibile e le impostazioni del browser. I dati esistenti non sono stati cancellati.</p>'}
